-- ============================================================
--  Тема «Умовні речення, Wishes, Unreal Past (Conditionals)»: теорія у кроковому форматі + вправи
--  Згенеровано з mig/conditionals.js — вручну не редагувати.
--  Потребує 06_theory_structure.sql. Повторний запуск безпечний.
-- ============================================================
begin;

alter table public.topics        add column if not exists subtopics jsonb not null default '[]'::jsonb;
alter table public.theory_blocks add column if not exists subtopic  text;
alter table public.exercises     add column if not exists subtopic  text;

create unique index if not exists uq_exercises_legacy_shared
  on public.exercises (legacy_id) where student_id is null;
alter table public.theory_blocks drop constraint if exists theory_blocks_kind_check;
alter table public.theory_blocks add constraint theory_blocks_kind_check
  check (kind in ('prose', 'hero', 'cases', 'formula', 'traps', 'pairs'));

insert into public.topics (slug, title, description, position, subtopics)
values ($g0$conditionals$g0$, $g1$Умовні речення, Wishes, Unreal Past (Conditionals)$g1$, $g2$Умовні речення 2 і 3 типу, wish та if only, Unreal Past (suppose, as if, it's time, I'd rather sb), had better і would rather, prefer.$g2$, 11, $g3$[{"slug":"cond_unreal","title":"Нереальні умови: якби…","description":"Умовні речення 2 і 3 типу, а також unless, provided, only if та інверсія Had I known / Were I you."},{"slug":"cond_wish","title":"Wish і if only: жаль і побажання","description":"Жаль про теперішнє й минуле, неможливе бажання змін, wish + would для роздратування."},{"slug":"cond_unrealpast","title":"Уявна ситуація: suppose, as if, it's time","description":"Past Simple для уявного теперішнього й Past Perfect для уявного минулого після suppose, as if, it's time, I'd rather sb."},{"slug":"cond_rather","title":"Порада й вибір: had better, would rather, prefer","description":"Коли краще зробити щось зараз, коли краще було б зробити інакше, і як висловити перевагу."},{"slug":"cond_mix","title":"Змішана практика: умови й побажання","description":"Тексти й перефразування, де змішано умовні речення, wish та Unreal Past. Окремої теорії тут немає.","mix":true}]$g3$::jsonb)
on conflict (slug) do update set title = excluded.title,
  description = excluded.description, position = excluded.position, subtopics = excluded.subtopics;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g4$th_1$g4$, $g5$Другий і третій тип: якби…$g5$, $g6$elementary$g6$, $g7$formula$g7$, $g8${"step":"Нереальні умови","kicker":"Базове розуміння","lead":"Коли умова нереальна, англійська «відсуває» час на крок назад. <b>Past Simple</b> говорить про нереальне теперішнє, <b>Past Perfect</b> — про нереальне минуле.","tiles":[{"role":"умова","label":"If + Past Simple","tone":"colour"},{"role":"наслідок","label":"would + bare infinitive","tone":"noun"}],"legend":[{"tone":"colour","label":"Тип 2: нереально зараз (If + Past Simple → would + V)"},{"tone":"noun","label":"Тип 3: нереально в минулому (If + Past Perfect → would have + V3)"}],"examples":[{"text":"If I <b>were</b> you, I <b>would leave</b> now.","plain":"If I were you, I would leave now.","note":"тип 2 · зараз"},{"text":"If I <b>had known</b> before, I <b>wouldn't have come</b>.","plain":"If I had known before, I wouldn't have come.","note":"тип 3 · минуле"},{"text":"If I <b>hadn't forgotten</b> my passport, I <b>could have travelled</b> abroad.","plain":"If I hadn't forgotten my passport, I could have travelled abroad.","note":"тип 3"},{"text":"If I <b>hadn't lost</b> my costume, I <b>could go</b> swimming now.","plain":"If I hadn't lost my costume, I could go swimming now.","note":"мішаний: минуле → зараз"}],"note":"Після <b>if</b> дієслово to be у Past Simple може мати форму <b>were</b> для всіх осіб: <i>If I were you</i> (так, а не <s>If I was you</s>, звучить правильніше й для іспитів)."}$g8$::jsonb, null, 0, $g9$cond_unreal$g9$
from public.topics where slug = $g10$conditionals$g10$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position, subtopic = excluded.subtopic;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g11$th_2$g11$, $g12$Замість if: unless, provided, only if та інверсія$g12$, $g13$intermediate$g13$, $g14$cases$g14$, $g15${"step":"Інші способи","kicker":"Конструкції на вибір","lead":"Умову можна передати не лише словом <b>if</b>. Дві конструкції змінюють порядок слів, їх треба впізнавати.","cards":[{"icon":"≠","title":"Unless = if … not","text":"Після <b>unless</b> дієслово стоїть у ствердній формі, <b>not</b> не додаємо.","example":"<b>Unless</b> you lend us money, we won't go.","examplePlain":"Unless you lend us money, we won't go."},{"icon":"✓","title":"Provided / as long as = if","text":"Умова, яка має виконатися: «за умови, що». Після них — теперішній час, а не will.","example":"You can borrow it <b>provided</b> you give it back.","examplePlain":"You can borrow it provided you give it back."},{"icon":"!","title":"Only if + інверсія","text":"Якщо <b>only if</b> стоїть на початку речення, у головній частині порядок слів як у питанні.","example":"<b>Only if</b> he changes it <b>will we sign</b> the contract.","examplePlain":"Only if he changes it will we sign the contract."},{"icon":"H","title":"Had + підмет + V3","text":"Інверсія без if для третього типу. Означає те саме, що <b>If … had</b>.","example":"<b>Had he not forgotten</b> the invitation, he would have gone.","examplePlain":"Had he not forgotten the invitation, he would have gone."},{"icon":"W","title":"Were + підмет","text":"Інверсія без if для другого типу, часто в порадах.","example":"<b>Were I</b> you, I would look for a better job.","examplePlain":"Were I you, I would look for a better job."},{"icon":"S","title":"Should + підмет + V","text":"Інверсія для реальної, але малоймовірної умови.","example":"We won't finish <b>should John not</b> turn up.","examplePlain":"We won't finish should John not turn up."}]}$g15$::jsonb, null, 1, $g16$cond_unreal$g16$
from public.topics where slug = $g17$conditionals$g17$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position, subtopic = excluded.subtopic;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g18$th_3$g18$, $g19$Wish: чотири ситуації$g19$, $g20$elementary$g20$, $g21$cases$g21$, $g22${"step":"Wish","kicker":"Що ми хочемо змінити","lead":"Після <b>I wish</b> (або <b>If only</b>) дієслово «відсувається» назад. Форма залежить від того, про що жаль.","cards":[{"icon":"1","title":"Жаль про теперішнє: Past Simple","text":"Ситуація зараз не така, як ми хочемо.","example":"I wish we <b>were</b> on holiday. (It's a pity we aren't.)","examplePlain":"I wish we were on holiday. It's a pity we aren't."},{"icon":"2","title":"Бракує вміння: could + V","text":"Жаль, що ми чогось не вміємо.","example":"I wish I <b>could speak</b> French. (BUT I can't.)","examplePlain":"I wish I could speak French. But I can't."},{"icon":"3","title":"Жаль про минуле: Past Perfect","text":"Щось сталося чи не сталося, і ми про це шкодуємо.","example":"I wish you <b>had listened</b> to me. (BUT you didn't.)","examplePlain":"I wish you had listened to me. But you didn't."},{"icon":"4","title":"Бажання змін: would + V","text":"Хочемо, щоб хтось змінив поведінку або щоб щось змінилось. Підмети різні, зміна малоймовірна.","example":"I wish he <b>would stop</b> lying. I wish it <b>would stop</b> snowing.","examplePlain":"I wish he would stop lying. I wish it would stop snowing."}],"axis":{"title":"Правило пальця","points":[{"label":"зараз","text":"<b>Past Simple</b>"},{"label":"уміння","text":"<b>could</b>"},{"label":"минуле","text":"<b>Past Perfect</b>"},{"label":"зміна","text":"<b>would</b>"}],"note":"Після I wish можна було б сказати <b>were</b> замість was для всіх осіб: <i>I wish he were / was more helpful.</i>"}}$g22$::jsonb, null, 2, $g23$cond_wish$g23$
from public.topics where slug = $g24$conditionals$g24$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position, subtopic = excluded.subtopic;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g25$th_4$g25$, $g26$Стоп-калька: wish і would$g26$, $g27$intermediate$g27$, $g28$traps$g28$, $g29${"step":"Стоп-калька 1","kicker":"Захист від рідної мови","lead":"Українське «хотів би, щоб…» часто переносять на wish дослівно. Ось типові збої.","items":[{"title":"«Шкода, що я не вмію водити»","bad":"I wish I can drive.","good":"I wish I <b>could</b> drive.","goodPlain":"I wish I could drive.","rule":"Після <i>wish</i> дієслово «відсувається»: can → could."},{"title":"«Шкода, що ми не на канікулах»","bad":"I wish we are on holiday.","good":"I wish we <b>were</b> on holiday.","goodPlain":"I wish we were on holiday.","rule":"Теперішній жаль — Past Simple, для to be краще <i>were</i>."},{"title":"«Шкода, що я не пішов»","bad":"I wish I didn't go.","good":"I wish I <b>hadn't gone</b>.","goodPlain":"I wish I hadn't gone.","rule":"Жаль про минуле — Past Perfect."},{"title":"«Хотів би я бути багатшим» (про себе)","bad":"I wish I would be richer.","good":"I wish I <b>were</b> richer.","goodPlain":"I wish I were richer.","rule":"Wish і would мають різні підмети. Про себе <s>I wish I would</s> не кажемо."},{"title":"«Шкода, що він так багато скаржиться»","bad":"I wish he doesn't complain.","good":"I wish he <b>wouldn't</b> complain.","goodPlain":"I wish he wouldn't complain.","rule":"Роздратування чужою звичкою: <i>wish + would</i>."},{"title":"«Шкода, що йде сніг»","bad":"I wish it stops snowing.","good":"I wish it <b>would stop</b> snowing.","goodPlain":"I wish it would stop snowing.","rule":"Хочемо зміни в майбутньому (і сумніваємось у ній): wish + would + V."}]}$g29$::jsonb, null, 3, $g30$cond_wish$g30$
from public.topics where slug = $g31$conditionals$g31$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position, subtopic = excluded.subtopic;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g32$th_5$g32$, $g33$Unreal Past: Past Simple і Past Perfect без минулого$g33$, $g34$intermediate$g34$, $g35$cases$g35$, $g36${"step":"Unreal Past","kicker":"Час «відсувається»","lead":"Past Simple може говорити про уявне теперішнє, а Past Perfect про уявне минуле. Це відбувається в шести конструкціях.","cards":[{"icon":"if","title":"Умовні речення","text":"Тип 2 — Past Simple, тип 3 — Past Perfect.","example":"If I <b>were</b> you, I'd leave. If I <b>had known</b>, I wouldn't have come.","examplePlain":"If I were you, I'd leave. If I had known, I wouldn't have come."},{"icon":"W","title":"Wish / if only","text":"Past Simple — теперішнє, Past Perfect — минуле.","example":"I wish she <b>worked</b> more efficiently. If only he <b>hadn't lied</b> to me.","examplePlain":"I wish she worked more efficiently. If only he hadn't lied to me."},{"icon":"R","title":"I'd rather / sooner + інший підмет","text":"Past Simple — про теперішнє й майбутнє, Past Perfect — про минуле.","example":"I'd rather you <b>left</b> the files here. I'd rather you <b>had not spoken</b> like that.","examplePlain":"I'd rather you left the files here. I'd rather you had not spoken like that."},{"icon":"S","title":"Suppose / supposing","text":"Уявна ситуація: Past Simple — про теперішнє, Past Perfect — про минуле.","example":"Suppose you <b>found</b> money, what would you do? Suppose she <b>hadn't reminded</b> you, would you have remembered?","examplePlain":"Suppose you found money, what would you do? Suppose she hadn't reminded you, would you have remembered?"},{"icon":"≈","title":"As if / as though","text":"Неправдиве порівняння: Past Simple — про теперішнє, Past Perfect — про минуле.","example":"He acts as if he <b>were</b> a genius. She looked at me as if she <b>had never seen</b> me before.","examplePlain":"He acts as if he were a genius. She looked at me as if she had never seen me before."},{"icon":"T","title":"It's (about / high) time","text":"«Давно пора». Дієслово у Past Simple, а сенс — теперішній.","example":"It's about time you <b>learnt</b> to drive.","examplePlain":"It's about time you learnt to drive."}]}$g36$::jsonb, null, 4, $g37$cond_unrealpast$g37$
from public.topics where slug = $g38$conditionals$g38$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position, subtopic = excluded.subtopic;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g39$th_6$g39$, $g40$Had better: «краще б…»$g40$, $g41$elementary$g41$, $g42$formula$g42$, $g43${"step":"Had better","kicker":"Порада з тиском","lead":"<b>Had better</b> звучить як порада, але майже з попередженням. Значення таке саме, як у <b>should</b>.","tiles":[{"role":"підмет","label":"I / you / he","tone":"noun"},{"role":"had better","label":"had better (not)","tone":"colour"},{"role":"bare infinitive","label":"+ V","tone":"age"}],"legend":[{"tone":"colour","label":"Про теперішнє й майбутнє: had better + V"},{"tone":"age","label":"Про минуле: It would have been better if + Past Perfect"}],"examples":[{"text":"He <b>had better not wait</b> any longer. (= He should not wait any longer.)","plain":"He had better not wait any longer.","note":"теперішнє / майбутнє"},{"text":"It <b>would have been better if</b> he <b>had phoned</b> us.","plain":"It would have been better if he had phoned us.","note":"минуле"},{"text":"You'<b>d better not wake</b> her up.","plain":"You'd better not wake her up.","note":"заперечення"}],"note":"Форма завжди <b>had</b>, але мова про теперішнє чи майбутнє. Після had better — інфінітив <b>без to</b>."}$g43$::jsonb, null, 5, $g44$cond_rather$g44$
from public.topics where slug = $g45$conditionals$g45$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position, subtopic = excluded.subtopic;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g46$th_7$g46$, $g47$Would rather і prefer: перевага$g47$, $g48$intermediate$g48$, $g49$cases$g49$, $g50${"step":"Would rather","kicker":"Що ми обираємо","lead":"Конструкції зі схожим значенням «віддаю перевагу» відрізняються формою дієслова після них.","cards":[{"icon":"1","title":"I'd rather + той самий підмет","text":"Після <b>I'd rather</b> — bare infinitive: про теперішнє й майбутнє — Present, про минуле — Perfect (have + V3).","example":"I'd rather <b>stay</b> in tonight. I'd rather <b>not have taken</b> the bus.","examplePlain":"I'd rather stay in tonight. I'd rather not have taken the bus."},{"icon":"2","title":"I'd rather + інший підмет","text":"Тут діє Unreal Past: Past Simple для теперішнього й майбутнього, Past Perfect для минулого.","example":"I'd rather you <b>didn't shout</b> so much. I'd rather you <b>had come</b> with me.","examplePlain":"I'd rather you didn't shout so much. I'd rather you had come with me."},{"icon":"3","title":"Prefer: загальна перевага","text":"<b>Prefer + gerund / noun + to + gerund / noun</b>.","example":"I prefer <b>watching</b> TV <b>to reading</b> books.","examplePlain":"I prefer watching TV to reading books."},{"icon":"4","title":"Prefer + to-інфінітив + rather than","text":"Загальна перевага: <b>prefer to V rather than V</b>. Після rather than — bare infinitive.","example":"I prefer <b>to eat</b> what I want <b>rather than count</b> calories.","examplePlain":"I prefer to eat what I want rather than count calories."},{"icon":"5","title":"Would prefer: конкретний вибір","text":"Одна конкретна ситуація: <b>would prefer to V rather than V</b>.","example":"I'd prefer <b>to play</b> football <b>rather than watch</b> it.","examplePlain":"I'd prefer to play football rather than watch it."},{"icon":"6","title":"Would rather + V + than + V","text":"Те саме, але без to в обох частинах.","example":"I'd rather <b>ski</b> than <b>skate</b>.","examplePlain":"I'd rather ski than skate."}]}$g50$::jsonb, null, 6, $g51$cond_rather$g51$
from public.topics where slug = $g52$conditionals$g52$
