insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g53$th_8$g53$, $g54$Стоп-калька: had better, would rather, prefer$g54$, $g55$intermediate$g55$, $g56$traps$g56$, $g57${"step":"Стоп-калька 2","kicker":"Ще шість пасток","lead":"Українське «краще б ти…» легко перенести в англійську з помилкою у формі дієслова.","items":[{"title":"«Тобі краще піти»","bad":"You had better to go.","good":"You had better <b>go</b>.","goodPlain":"You had better go.","rule":"Після had better — bare infinitive без to."},{"title":"«Краще б вона не приходила»","bad":"I'd rather she doesn't come.","good":"I'd rather she <b>didn't come</b>.","goodPlain":"I'd rather she didn't come.","rule":"Інший підмет після would rather — Past Simple для теперішнього."},{"title":"«Краще б ти тоді прийшов»","bad":"I'd rather you came yesterday.","good":"I'd rather you <b>had come</b> yesterday.","goodPlain":"I'd rather you had come yesterday.","rule":"Про минуле — Past Perfect."},{"title":"«Я б краще залишився вдома»","bad":"I'd rather to stay at home.","good":"I'd rather <b>stay</b> at home.","goodPlain":"I'd rather stay at home.","rule":"Після would rather — інфінітив без to."},{"title":"«Я люблю плавання більше, ніж біг»","bad":"I prefer swimming than running.","good":"I prefer swimming <b>to</b> running.","goodPlain":"I prefer swimming to running.","rule":"Prefer + gerund + <b>to</b> + gerund. Than тут не вживається."},{"title":"«Мені краще було б залишитися»","bad":"I had better stayed.","good":"It would have been better if I <b>had stayed</b>.","goodPlain":"It would have been better if I had stayed.","rule":"Про минуле had better не вживається. Є <i>It would have been better if + Past Perfect</i>."}]}$g57$::jsonb, null, 7, $g58$cond_rather$g58$
from public.topics where slug = $g59$conditionals$g59$
