with t as (select id from public.topics where slug = $g765$conditionals$g765$)
insert into public.exercises (topic_id, legacy_id, type, level, payload, position, source, subtopic)
select t.id, v.lid, v.type, v.level, v.payload::jsonb, v.pos, 'book', v.sub from t, (values
  ($g60$cond_ex11_1$g60$, $g61$choice$g61$, $g62$intermediate$g62$, $g63${"id":"cond_ex11_1","level":"intermediate","group":11,"gord":11,"no":1,"instruction":"Rewrite the text using wishes or if-clauses, as in the example. (Dear Mary, … With love, Lisa)","before":"I wish I","options":["hadn't had","didn't have","wouldn't have"],"after":"such a terrible day today.","correct":"hadn't had","explanation":"Жаль про минуле (день уже був): wish + Past Perfect."}$g63$, 0, $g64$cond_wish$g64$),
  ($g65$cond_ex11_2$g65$, $g66$choice$g66$, $g67$intermediate$g67$, $g68${"id":"cond_ex11_2","level":"intermediate","group":11,"gord":11,"no":2,"instruction":"Rewrite the text using wishes or if-clauses, as in the example. (Dear Mary, … With love, Lisa)","before":"If my neighbour","options":["hadn't been","wasn't","weren't"],"after":"ill, I wouldn't have offered to take Rex for a walk.","correct":"hadn't been","explanation":"Тип 3: If + Past Perfect. Сусідка була хвора в минулому."}$g68$, 1, $g69$cond_wish$g69$),
  ($g70$cond_ex11_5$g70$, $g71$choice$g71$, $g72$intermediate$g72$, $g73${"id":"cond_ex11_5","level":"intermediate","group":11,"gord":11,"no":5,"instruction":"Rewrite the text using wishes or if-clauses, as in the example. (Dear Mary, … With love, Lisa)","before":"I wish I","options":["hadn't taken","didn't take","wouldn't take"],"after":"the dog for a walk.","correct":"hadn't taken","explanation":"Жаль про минуле: wish + Past Perfect. (В оригіналі це shouldn't have taken.)"}$g73$, 2, $g74$cond_wish$g74$),
