  ($g715$cond_ex15_3$g715$, $g716$abcd$g716$, $g717$advanced$g717$, $g718${"id":"cond_ex15_3","level":"advanced","group":15,"gord":15,"no":3,"instruction":"Read the following situations, then make sentences using would rather or had better.","q":"3. You want to be left alone to read and don't want to go to the cinema.","options":["A) I'd rather to be left alone to read than going to the cinema.","B) I'd rather being left alone to read than go to the cinema.","C) I'd rather be left alone to read than go to the cinema.","D) I'd rather I had been left alone to read than to go to the cinema."],"correct":2,"explanation":"Той самий підмет: would rather + bare infinitive + than + bare infinitive."}$g718$, 22, $g719$cond_rather$g719$),
  ($g720$cond_ex15_4$g720$, $g721$abcd$g721$, $g722$advanced$g722$, $g723${"id":"cond_ex15_4","level":"advanced","group":15,"gord":15,"no":4,"instruction":"Read the following situations, then make sentences using would rather or had better.","q":"4. It would be more sensible for you to go and rest for an hour.","options":["A) You had better to go and rest for an hour.","B) You had better going to rest for an hour.","C) You had better go and rest for an hour.","D) You would better go and rest for an hour."],"correct":2,"explanation":"Had better + bare infinitive: порада з тиском."}$g723$, 23, $g724$cond_rather$g724$),
  ($g725$cond_ex15_5$g725$, $g726$abcd$g726$, $g727$advanced$g727$, $g728${"id":"cond_ex15_5","level":"advanced","group":15,"gord":15,"no":5,"instruction":"Read the following situations, then make sentences using would rather or had better.","q":"5. I would prefer to spend more time in Spain and not go home.","options":["A) I'd rather to spend more time in Spain than going home.","B) I'd rather spending more time in Spain than go home.","C) I'd rather spend more time in Spain than go home.","D) I'd rather spend more time in Spain than to go home."],"correct":2,"explanation":"Would rather: обидві частини без to."}$g728$, 24, $g729$cond_rather$g729$),
  ($g730$cond_ex15_6$g730$, $g731$abcd$g731$, $g732$advanced$g732$, $g733${"id":"cond_ex15_6","level":"advanced","group":15,"gord":15,"no":6,"instruction":"Read the following situations, then make sentences using would rather or had better.","q":"6. We should have waited for him at home.","options":["A) It would have been better if we waited for him at home.","B) It would be better if we had waited for him at home.","C) It would have been better if we had waited for him at home.","D) It would have been better if we would have waited for him at home."],"correct":2,"explanation":"Для минулого had better не вживаємо: It would have been better if + Past Perfect."}$g733$, 25, $g734$cond_rather$g734$),
  ($g735$cond_ex15_7$g735$, $g736$abcd$g736$, $g737$advanced$g737$, $g738${"id":"cond_ex15_7","level":"advanced","group":15,"gord":15,"no":7,"instruction":"Read the following situations, then make sentences using would rather or had better.","q":"7. Mary always wears horrible orange lipstick. You wish she wouldn't.","options":["A) I'd rather Mary doesn't wear horrible orange lipstick.","B) I'd rather Mary wouldn't wear horrible orange lipstick.","C) I'd rather Mary didn't wear horrible orange lipstick.","D) I'd rather Mary not to wear horrible orange lipstick."],"correct":2,"explanation":"Інший підмет після would rather: Past Simple."}$g738$, 26, $g739$cond_rather$g739$),
  ($g740$cond_ex15_8$g740$, $g741$abcd$g741$, $g742$advanced$g742$, $g743${"id":"cond_ex15_8","level":"advanced","group":15,"gord":15,"no":8,"instruction":"Read the following situations, then make sentences using would rather or had better.","q":"8. Your friend turns up late and you are angry with him.","options":["A) You had better not to be late again.","B) You had better don't be late again.","C) You had better not be late again.","D) You would better not be late again."],"correct":2,"explanation":"Had better not + bare infinitive: попередження."}$g743$, 27, $g744$cond_rather$g744$),
  ($g745$cond_exOD10_1$g745$, $g746$abcd$g746$, $g747$intermediate$g747$, $g748${"id":"cond_exOD10_1","level":"intermediate","group":"OD10","gord":20,"no":1,"groupTitle":"Oral Development 10","instruction":"Look at the pictures, then make sentences using conditionals or wishes to say what each person is thinking. (Choose the best thought.)","q":"1. Школярка пізно ввечері робить домашнє завдання. Що вона думає?","options":["A) I wish I hadn't so much homework yesterday.","B) I wish I wouldn't have so much homework.","C) I wish I didn't have so much homework.","D) I wish I don't have so much homework."],"correct":2,"explanation":"Теперішня ситуація: wish + Past Simple."}$g748$, 28, $g749$cond_mix$g749$),
  ($g750$cond_exOD10_2$g750$, $g751$abcd$g751$, $g752$intermediate$g752$, $g753${"id":"cond_exOD10_2","level":"intermediate","group":"OD10","gord":20,"no":2,"groupTitle":"Oral Development 10","instruction":"Look at the pictures, then make sentences using conditionals or wishes to say what each person is thinking. (Choose the best thought.)","q":"2. Дівчинка сидить сама й сумує. Що вона думає?","options":["A) If only I have someone to talk to.","B) If only I would have someone to talk to.","C) If only I had someone to talk to.","D) If only I had had someone to talk to now."],"correct":2,"explanation":"If only + Past Simple — жаль про теперішнє."}$g753$, 29, $g754$cond_mix$g754$),
  ($g755$cond_exOD10_3$g755$, $g756$abcd$g756$, $g757$intermediate$g757$, $g758${"id":"cond_exOD10_3","level":"intermediate","group":"OD10","gord":20,"no":3,"groupTitle":"Oral Development 10","instruction":"Look at the pictures, then make sentences using conditionals or wishes to say what each person is thinking. (Choose the best thought.)","q":"3. Чоловік із головним болем сидить за ноутбуком. Що він думає?","options":["A) If I finished the report earlier, I wouldn't have been so stressed now.","B) If I have finished the report earlier, I won't be stressed now.","C) If I had finished the report earlier, I wouldn't be so stressed now.","D) If I had finished the report earlier, I wouldn't have been so stressed now."],"correct":2,"explanation":"Мішаний тип: минуле (had finished) → теперішній результат (wouldn't be so stressed now)."}$g758$, 30, $g759$cond_mix$g759$),
  ($g760$cond_exOD10_4$g760$, $g761$abcd$g761$, $g762$intermediate$g762$, $g763${"id":"cond_exOD10_4","level":"intermediate","group":"OD10","gord":20,"no":4,"groupTitle":"Oral Development 10","instruction":"Look at the pictures, then make sentences using conditionals or wishes to say what each person is thinking. (Choose the best thought.)","q":"4. Чоловік сидить на лавці, обхопивши голову руками. Що він думає?","options":["A) I wish I didn't lose my job.","B) I wish I wouldn't lose my job.","C) I wish I hadn't lost my job.","D) I wish I haven't lost my job."],"correct":2,"explanation":"Жаль про минуле: wish + Past Perfect."}$g763$, 31, $g764$cond_mix$g764$)
) as v(lid, type, level, payload, pos, sub)
on conflict (legacy_id) where student_id is null do update set
  topic_id = excluded.topic_id, type = excluded.type, level = excluded.level,
  payload = excluded.payload, position = excluded.position, subtopic = excluded.subtopic;

commit;

-- Контроль: блоки теорії за рівнями та кількість вправ за типами
select 'теорія' as що, tb.level as деталь, count(*) from public.theory_blocks tb join public.topics t on t.id = tb.topic_id
  where t.slug = $g768$conditionals$g768$ group by tb.level
union all
select 'вправи', e.type, count(*) from public.exercises e join public.topics t on t.id = e.topic_id
  where t.slug = $g769$conditionals$g769$ and e.student_id is null group by e.type order by 1, 2;

-- Контроль по підтемах: блоки теорії та вправи
select s.sub as підтема, (select count(*) from public.theory_blocks b where b.topic_id = t.id and b.subtopic = s.sub) as теорія,
       (select count(*) from public.exercises e where e.topic_id = t.id and e.subtopic = s.sub and e.student_id is null) as вправи
  from public.topics t cross join lateral jsonb_array_elements(t.subtopics) with ordinality as x(j, ord)
  cross join lateral (select x.j->>'slug' as sub) s where t.slug = $g770$conditionals$g770$ order by x.ord;
